{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, the closest structural analogue (Morgan 0.236), achieved only a 0.12 CSF:plasma ratio in monkeys and little brain distribution, directly demonstrating poor CNS access for a large glycosylated polyketide sharing the query's polyhydroxylated/glycosidic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "DX-52-1, a polycyclic natural-product derivative with a basic amine and multiple polar groups, showed a brain-to-blood ratio of about 0.02 in mice, indicating very limited BBB crossing; this transfers to the query's ionizable aminosugar and polar anthracycline core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Digitoxin, a cardiac glycoside with a lipophilic steroid core and attached sugars, had a CSF/plasma ratio of only 0.01-0.03 in dogs, showing that glycosylation and high polarity can dominate over lipophilic cores and prevent meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Emodin-8-O-β-D-glucoside, an anthraquinone glycoside, was detected in rat brain after dosing, providing some evidence that certain glycosylated anthraquinones can achieve brain distribution; however, it lacks the ionizable aminosugar and much higher polarity of the query, limiting transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "fail - meaningful CNS access is unlikely; direct evidence from structurally related glycosylated/polar natural products shows poor CSF/brain penetration, and the query's very high polarity, size, and ionizable aminosugar make passive BBB diffusion negligible.",
  "evidence_gaps": [
    "No direct brain/CSF pharmacokinetic data for the query molecule.",
    "Morgan similarities to experimental analogues are low (0.20-0.24), limiting quantitative transfer.",
    "Efflux transporter substrate status of the query is not directly measured.",
    "Some glycoside/anthraquinone analogues show brain distribution, so active uptake or disease-state BBB disruption cannot be fully excluded."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

